import{_ as e,c as a,o as i,az as s}from"./chunks/framework.BiJC-IFK.js";const u=JSON.parse('{"title":"Welcome to AdditionalDistributions.jl","description":"","frontmatter":{"layout":"home","hero":{"name":"AdditionalDistributions.jl","text":null,"tagline":"An extension of Distributions.jl package.","image":{"src":"logo.png","alt":"AdditionalDistributions.jl"},"actions":[{"theme":"brand","text":"Getting started","link":"getting_started"},{"theme":"alt","text":"View on Github","link":"https://github.com/Santymax98/AdditionalDistributions.jl"},{"theme":"alt","text":"Bestiary","link":"/bestiary/continuous"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),n={name:"index.md"};function o(r,t,l,d,c,p){return i(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="Welcome-to-AdditionalDistributions.jl" tabindex="-1">Welcome to AdditionalDistributions.jl <a class="header-anchor" href="#Welcome-to-AdditionalDistributions.jl" aria-label="Permalink to &quot;Welcome to AdditionalDistributions.jl {#Welcome-to-AdditionalDistributions.jl}&quot;">​</a></h1><p>The <a href="https://github.com/Santymax98/AdditionalDistributions.jl" target="_blank" rel="noreferrer"><em>AdditionalDistributions.jl</em></a> package is a comprehensive extension of <a href="https://github.com/JuliaStats/Distributions.jl" target="_blank" rel="noreferrer"><em>Distributions.jl</em></a>, designed to expand its functionality by incorporating both <strong>discrete</strong>, <strong>continuous</strong>, and <strong>multivariate</strong> probability distributions not available in the base package. It provides a unified, research-grade framework for probabilistic modeling, simulation, and numerical evaluation of advanced statistical distributions.</p><hr><h2 id="Overview" tabindex="-1">Overview <a class="header-anchor" href="#Overview" aria-label="Permalink to &quot;Overview {#Overview}&quot;">​</a></h2><p>With <em>AdditionalDistributions</em>, you can:</p><ul><li><p><strong>Sample from distributions:</strong> Draw random samples from classical and novel models.</p></li><li><p><strong>Compute densities and probabilities:</strong> Access <code>pdf</code>, <code>cdf</code>, and <code>logpdf</code> for a wide range of families.</p></li><li><p><strong>Evaluate multivariate probabilities:</strong> Compute rectangular probabilities for Gaussian and Student’s <em>t</em> models using a high-performance QMC integrator.</p></li><li><p><strong>Calculate statistical properties:</strong> Obtain mean, variance, skewness, kurtosis, entropy, and characteristic functions.</p></li><li><p><strong>Extend or define new distributions:</strong> Create custom statistical models compatible with <code>Distributions.jl</code>’s interface.</p></li></ul><hr><h2 id="Highlights" tabindex="-1">Highlights <a class="header-anchor" href="#Highlights" aria-label="Permalink to &quot;Highlights {#Highlights}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Category</th><th style="text-align:right;">Feature</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">🧮 <strong>Compatibility</strong></td><td style="text-align:right;">Full API parity with <code>Distributions.jl</code></td><td style="text-align:right;">Supports <code>pdf</code>, <code>cdf</code>, <code>rand</code>, <code>entropy</code>, <code>params</code>, etc.</td></tr><tr><td style="text-align:right;">📈 <strong>Coverage</strong></td><td style="text-align:right;">Zero-inflated, generalized, heavy-tailed families</td><td style="text-align:right;">e.g., <code>ZINB</code>, <code>ZIP</code>, <code>Lomax</code>, <code>BurrXII</code>, <code>BetaNegBinomial</code>, …</td></tr><tr><td style="text-align:right;">🔬 <strong>Multivariate CDFs</strong></td><td style="text-align:right;">QMC-based <code>cdf</code> for <code>MvGaussian</code> and <code>MvTStudent</code></td><td style="text-align:right;">Reproducible, accurate results typically within <code>1e-5</code>–<code>1e-6</code>.</td></tr><tr><td style="text-align:right;">🧩 <strong>Design</strong></td><td style="text-align:right;">Modular and research-oriented</td><td style="text-align:right;">Mirrors structure, style, and tests from <code>Distributions.jl</code>.</td></tr><tr><td style="text-align:right;">🧠 <strong>Validation</strong></td><td style="text-align:right;">Cross-checked against <code>mvtnorm</code> (R, Genz &amp; Bretz 2002)</td><td style="text-align:right;">Ensures correctness and reproducibility across ecosystems.</td></tr></tbody></table><hr><h2 id="Motivation" tabindex="-1">Motivation <a class="header-anchor" href="#Motivation" aria-label="Permalink to &quot;Motivation {#Motivation}&quot;">​</a></h2><p>Many probability distributions and accurate multivariate CDFs remain unavailable or fragmented across Julia packages. <strong>AdditionalDistributions.jl</strong> aims to unify them under a consistent API, enabling both theoretical and applied work in statistics, econometrics, and data science.</p><p>The package is also a testbed for <strong>algorithmic optimization</strong> — including Quasi-Monte-Carlo integration, low-discrepancy sequences, and vectorized numerical transforms — with the goal of eventually contributing mature implementations back to <code>Distributions.jl</code>.</p><hr><h2 id="Results-illustrative-comparison" tabindex="-1">Results (illustrative comparison) <a class="header-anchor" href="#Results-illustrative-comparison" aria-label="Permalink to &quot;Results (illustrative comparison) {#Results-illustrative-comparison}&quot;">​</a></h2><p>Representative results under identical conditions (same machine, same <code>Σ</code>, same limits <code>[a,b]</code>, same <code>m</code>, fixed seed):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Case</th><th style="text-align:right;">Method</th><th style="text-align:right;">Probability <code>p</code></th><th style="text-align:right;">Reported error</th><th style="text-align:right;">Note</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>MVN</strong> (d=6, m=50 000)</td><td style="text-align:right;"><code>MvGaussian</code> (QMC)</td><td style="text-align:right;"><code>0.2130609785</code></td><td style="text-align:right;"><code>4.19e-5</code></td><td style="text-align:right;"><code>inform = 1</code> (tolerance not met)</td></tr><tr><td style="text-align:right;"><strong>MVN</strong> (d=6, m=50 000)</td><td style="text-align:right;"><code>MvNormalCDF.jl</code> (Genz–Bretz)</td><td style="text-align:right;"><code>0.2130493052</code></td><td style="text-align:right;"><code>1.42e-5</code></td><td style="text-align:right;">smaller error in this scenario</td></tr></tbody></table><p>For <strong>Student’s <em>t</em></strong> (e.g., <code>d=5</code>, <code>ν=10</code>, <code>m=20 000</code>), typical outputs are of the form:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p ≈ 0.2468,  error ≈ 8.2e-5,  inform = 0</span></span></code></pre></div><p><strong>Interpretation</strong></p><ul><li><p>QMC yields <strong>reproducible</strong> results (fixed seed) and competitive accuracy.</p></li><li><p>Reported errors are <strong>estimators</strong>, not strict bounds; they vary with <code>m</code>, dimension, correlation, and region <code>[a,b]</code>.</p></li><li><p>In some problems Genz–Bretz reports smaller errors for the same <code>m</code>; in others QMC matches or surpasses. The goal here is <strong>transparent, honest comparability</strong>.</p></li></ul><hr><h2 id="Usage-snippets" tabindex="-1">Usage snippets <a class="header-anchor" href="#Usage-snippets" aria-label="Permalink to &quot;Usage snippets {#Usage-snippets}&quot;">​</a></h2><h3 id="Multivariate-Gaussian-rectangular-CDF" tabindex="-1">Multivariate Gaussian (rectangular CDF) <a class="header-anchor" href="#Multivariate-Gaussian-rectangular-CDF" aria-label="Permalink to &quot;Multivariate Gaussian (rectangular CDF) {#Multivariate-Gaussian-rectangular-CDF}&quot;">​</a></h3><div class="language-example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>using AdditionalDistributions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>μ = zeros(5)</span></span>
<span class="line"><span>Σ = [1.0 0.6 0.3 0.1 0.0;</span></span>
<span class="line"><span>     0.6 1.0 0.5 0.3 0.1;</span></span>
<span class="line"><span>     0.3 0.5 1.0 0.6 0.3;</span></span>
<span class="line"><span>     0.1 0.3 0.6 1.0 0.6;</span></span>
<span class="line"><span>     0.0 0.1 0.3 0.6 1.0]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>a = fill(-1.0, 5)</span></span>
<span class="line"><span>b = fill( 1.0, 5)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>d = MvGaussian(μ, Σ)</span></span>
<span class="line"><span>p = cdf(d, a, b; m=50_000)                 # or full=true to get (value, error, inform)</span></span></code></pre></div><h3 id="Multivariate-Student’s-t-rectangular-CDF" tabindex="-1">Multivariate Student’s <em>t</em> (rectangular CDF) <a class="header-anchor" href="#Multivariate-Student’s-t-rectangular-CDF" aria-label="Permalink to &quot;Multivariate Student’s _t_ (rectangular CDF) {#Multivariate-Student’s-t-rectangular-CDF}&quot;">​</a></h3><div class="language-example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ν = 10</span></span>
<span class="line"><span>Σ = [1.0 0.4 0.2 0.1 0.05;</span></span>
<span class="line"><span>     0.4 1.0 0.5 0.2 0.1;</span></span>
<span class="line"><span>     0.2 0.5 1.0 0.4 0.2;</span></span>
<span class="line"><span>     0.1 0.2 0.4 1.0 0.3;</span></span>
<span class="line"><span>     0.05 0.1 0.2 0.3 1.0]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>a = fill(-0.5, 5)</span></span>
<span class="line"><span>b = fill( 0.5, 5)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>d_t = MvTStudent(ν, zeros(5), Σ)</span></span>
<span class="line"><span>val, err, info = cdf(d_t, a, b; m=20_000, full=true)</span></span></code></pre></div><hr><h2 id="Methodological-notes" tabindex="-1">Methodological notes <a class="header-anchor" href="#Methodological-notes" aria-label="Permalink to &quot;Methodological notes {#Methodological-notes}&quot;">​</a></h2><ul><li><p><strong>Algorithms</strong>:</p><ul><li><code>MvGaussian</code> / <code>MvTStudent</code> use QMC with Richtmyer lattices + Cranley–Patterson shifts; optional antithetic reflection in Gaussian coordinates; reproducibility via seeded RNG.</li></ul></li><li><p><strong>Parameters that matter</strong>:</p><ul><li>Budget <code>m</code>, <strong>dimension</strong> <code>d</code>, <strong>correlation</strong> structure, geometry of <code>[a,b]</code>. For Student’s <em>t</em>, also <code>ν</code> and the standardization to correlation.</li></ul></li><li><p><strong>Reporting</strong>:</p><ul><li><code>full=true</code> returns <code>(value, error, inform)</code>. <code>inform = 1</code> indicates tolerance not met under the current <code>m</code>; increase <code>m</code> or relax tolerances.</li></ul></li></ul><hr><h2 id="Roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#Roadmap" aria-label="Permalink to &quot;Roadmap {#Roadmap}&quot;">​</a></h2><ul><li><p>Extend coverage to <strong>Generalized Hyperbolic</strong>, <strong>Skew-t</strong>, <strong>Variance-Gamma</strong>.</p></li><li><p>Add parameter fitting (<code>fit_mle</code>, <code>fit_map</code>) for new families.</p></li><li><p>Explore GPU-assisted QMC for high-dimensional CDFs.</p></li><li><p>Improve diagnostics (<code>inform</code>) and optional convergence logging.</p></li><li><p>Publish reproducible comparisons across Julia and R ecosystems.</p></li></ul><hr><h2 id="Contributing" tabindex="-1">Contributing <a class="header-anchor" href="#Contributing" aria-label="Permalink to &quot;Contributing {#Contributing}&quot;">​</a></h2><p>We follow the development guidelines and testing conventions of <a href="https://github.com/JuliaStats/Distributions.jl" target="_blank" rel="noreferrer"><em>Distributions.jl</em></a>:</p><ul><li><p>Use <code>@testitem</code> blocks with explicit tolerances and seeded randomness when applicable.</p></li><li><p>Include <code>doctest</code> examples in docstrings.</p></li><li><p>Keep methods type-stable, memory-aware, and numerically robust.</p></li></ul><p><strong>Ways to contribute</strong></p><ol><li><p><strong>Report issues</strong> with clear minimal reproductions.</p></li><li><p><strong>Propose improvements</strong> (performance, modularity, memory) via PRs.</p></li><li><p><strong>Discuss algorithms</strong> (QMC variance reduction, pivots, transforms).</p></li><li><p><strong>Documentation</strong> (examples, edge cases, methodological notes).</p></li></ol><hr><h2 id="Related-ecosystem" tabindex="-1">Related ecosystem <a class="header-anchor" href="#Related-ecosystem" aria-label="Permalink to &quot;Related ecosystem {#Related-ecosystem}&quot;">​</a></h2><ul><li><p><a href="https://github.com/JuliaStats/Distributions.jl" target="_blank" rel="noreferrer"><code>Distributions.jl</code></a> — Base statistical library.</p></li><li><p><a href="https://github.com/JuliaStats/MvNormalCDF.jl" target="_blank" rel="noreferrer"><code>MvNormalCDF.jl</code></a> — Genz–Bretz MVN CDF.</p></li><li><p><a href="https://github.com/JuliaStats/StatsBase.jl" target="_blank" rel="noreferrer"><code>StatsBase.jl</code></a> — Foundational statistics.</p></li></ul><hr><h2 id="Citation" tabindex="-1">Citation <a class="header-anchor" href="#Citation" aria-label="Permalink to &quot;Citation {#Citation}&quot;">​</a></h2><p>If you use <em>AdditionalDistributions.jl</em> in academic work, please cite:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S. Jiménez (2025). AdditionalDistributions.jl — Advanced and Extended Probability Distributions in Julia.</span></span>
<span class="line"><span>Available at: https://github.com/Santymax98/AdditionalDistributions.jl</span></span></code></pre></div><hr><p><strong>Author:</strong> Santiago Jiménez <strong>License:</strong> MIT <strong>Repository:</strong> <a href="https://github.com/Santymax98/AdditionalDistributions.jl" target="_blank" rel="noreferrer">Santymax98/AdditionalDistributions.jl</a></p>`,48)])])}const h=e(n,[["render",o]]);export{u as __pageData,h as default};
